INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 0, jsonb_build_object('text', $txt$Masalah: Proyek Arduino Butuh Suara$txt$) FROM madevi.articles v WHERE v.business_code = 'TUT-ELEKTRONIK14-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Banyak proyek Arduino terasa hampa tanpa suara: alarm peringatan, nada tombol, atau efek bunyi robot. Layar LCD memang bisa menampilkan informasi, tetapi suara langsung menarik perhatian. Buzzer adalah komponen termurah dan termudah untuk menambahkan suara ke proyekmu — harganya ribuan rupiah dan hanya butuh satu pin digital.$txt$) FROM madevi.articles v WHERE v.business_code = 'TUT-ELEKTRONIK14-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 2, jsonb_build_object('text', $txt$Penjelasan: Cara Kerja Buzzer$txt$) FROM madevi.articles v WHERE v.business_code = 'TUT-ELEKTRONIK14-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Ada dua jenis buzzer: aktif dan pasif. Buzzer aktif berbunyi sendiri begitu diberi tegangan DC 5V — cocok untuk alarm sederhana. Buzzer pasif butuh sinyal berfrekuensi lewat fungsi tone() dan bisa menghasilkan nada berbeda-beda — inilah yang dipakai untuk memainkan melodi. Buzzer pasif memiliki kaki positif (+) yang lebih panjang; kaki negatif (-) biasanya ditandai garis pada bodinya.$txt$) FROM madevi.articles v WHERE v.business_code = 'TUT-ELEKTRONIK14-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 4, jsonb_build_object('text', $txt$Alat dan Bahan$txt$) FROM madevi.articles v WHERE v.business_code = 'TUT-ELEKTRONIK14-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'LIST', 5, jsonb_build_object('items', ARRAY[$txt$Arduino Uno (atau Nano/ESP32)$txt$, $txt$Buzzer pasif 5V$txt$, $txt$Breadboard dan kabel jumper$txt$, $txt$Resistor 100 ohm (opsional, pengaman)$txt$, $txt$Kabel USB dan komputer dengan Arduino IDE$txt$]) FROM madevi.articles v WHERE v.business_code = 'TUT-ELEKTRONIK14-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 6, jsonb_build_object('text', $txt$Langkah-langkah$txt$) FROM madevi.articles v WHERE v.business_code = 'TUT-ELEKTRONIK14-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$1) Rangkaian: hubungkan kaki (+) buzzer ke pin digital 8 dan kaki (-) ke GND. 2) Bunyi bip pertama: unggah program tone(8, 1000, 500) — dengarkan nada 1000 Hz selama setengah detik; coba ubah frekuensi (262, 523, 880 Hz) untuk merasakan perbedaan nada. 3) Memainkan melodi: buat array nada dan durasi, mainkan berurutan — contoh 'Twinkle Twinkle': 262, 262, 392, 392, 440, 440, 392 dengan jeda noTone(8) singkat antar nada. 4) Alarm sirene: naikkan frekuensi bertahap dari 200 ke 2000 Hz dalam loop; untuk bunyi tombol cukup tone(8, 1500, 50) tiap tombol ditekan.$txt$) FROM madevi.articles v WHERE v.business_code = 'TUT-ELEKTRONIK14-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 8, jsonb_build_object('text', $txt$Risiko dan Kesalahan Umum$txt$) FROM madevi.articles v WHERE v.business_code = 'TUT-ELEKTRONIK14-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'LIST', 9, jsonb_build_object('items', ARRAY[$txt$Buzzer tidak bunyi: kaki terbalik atau salah pin — cek wiring dan nomor pin di program$txt$, $txt$Suara sangat pelan: arus pin kurang — tambahkan transistor sebagai penguat bila perlu$txt$, $txt$Nada fals: frekuensi di luar jangkauan buzzer (umumnya 100 Hz – 10 kHz)$txt$, $txt$Program macet: hindari delay() panjang bila proyek butuh respons tombol — gunakan millis()$txt$]) FROM madevi.articles v WHERE v.business_code = 'TUT-ELEKTRONIK14-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 10, jsonb_build_object('text', $txt$Penyelesaian dan Tindak Lanjut$txt$) FROM madevi.articles v WHERE v.business_code = 'TUT-ELEKTRONIK14-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'PARAGRAPH', 11, jsonb_build_object('text', $txt$Proyek berhasil jika buzzer berbunyi bip, nada berbeda terdengar berbeda, dan melodi sederhana dapat dimainkan. Langkah berikutnya: gabungkan buzzer dengan sensor (alarm gerak dengan PIR, alarm suhu dengan DHT11), buat piano mini 8 tombol, atau mainkan lagu favoritmu dengan mencari not angkanya di internet.$txt$) FROM madevi.articles v WHERE v.business_code = 'TUT-ELEKTRONIK14-001';
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 0, jsonb_build_object('text', $txt$Masalah: Sayur Asem Kurang Segar$txt$) FROM madevi.articles v WHERE v.business_code = 'TUT-MASAK19-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Sayur asem yang enak itu kuahnya bening, asamnya segar, dan sayurannya tidak lembek. Banyak yang gagal: kuah keruh, rasa asamnya tengik, atau jagungnya masih mentah sementara labunya sudah hancur. Padahal sayur asem adalah masakan rumahan paling mudah — asal tahu urutan memasukkan sayuran dan takaran asam yang pas.$txt$) FROM madevi.articles v WHERE v.business_code = 'TUT-MASAK19-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 2, jsonb_build_object('text', $txt$Penjelasan: Kunci Sayur Asem Enak$txt$) FROM madevi.articles v WHERE v.business_code = 'TUT-MASAK19-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Rasa khas sayur asem datang dari tiga asam alami: asam jawa, belimbing wuluh, dan kadang tomat. Bumbu dasarnya sederhana: bawang merah, bawang putih, kemiri, cabai, lengkuas, dan daun salam. Rahasianya ada pada urutan: bahan yang lama matang masuk duluan, yang cepat matang belakangan. Jangan mengaduk berlebihan setelah asam masuk agar kuah tetap bening.$txt$) FROM madevi.articles v WHERE v.business_code = 'TUT-MASAK19-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 4, jsonb_build_object('text', $txt$Bahan-bahan dan Bumbu (4-5 porsi)$txt$) FROM madevi.articles v WHERE v.business_code = 'TUT-MASAK19-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'LIST', 5, jsonb_build_object('items', ARRAY[$txt$1 buah jagung manis, potong 4; 100 gram labu siam potong dadu; 5 kacang panjang; 1 genggam daun melinjo + 50 gram buah melinjo; 1 terong ungu kecil$txt$, $txt$2 cm lengkuas memarkan; 2 lembar daun salam; 1 sdm asam jawa dilarutkan; 3 belimbing wuluh (opsional)$txt$, $txt$Bumbu halus: 5 bawang merah, 3 bawang putih, 2 kemiri sangrai, 3 cabai merah keriting$txt$, $txt$Garam, gula merah, kaldu secukupnya; air 1,5 liter$txt$]) FROM madevi.articles v WHERE v.business_code = 'TUT-MASAK19-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 6, jsonb_build_object('text', $txt$Langkah Memasak$txt$) FROM madevi.articles v WHERE v.business_code = 'TUT-MASAK19-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$1) Didihkan 1,5 liter air, masukkan jagung, buah melinjo, lengkuas, dan daun salam — masak 10 menit. 2) Masukkan bumbu halus, labu siam, dan terong; masak 5-7 menit, bumbui garam, gula merah, dan kaldu hingga rasa gurih pas. 3) Masukkan larutan asam jawa, belimbing wuluh, kacang panjang, dan daun melinjo — masak cukup 3-4 menit, jangan aduk berlebihan. Matikan api dan cicipi: segar, asam, gurih, sedikit manis.$txt$) FROM madevi.articles v WHERE v.business_code = 'TUT-MASAK19-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 8, jsonb_build_object('text', $txt$Risiko dan Kesalahan Umum$txt$) FROM madevi.articles v WHERE v.business_code = 'TUT-MASAK19-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'LIST', 9, jsonb_build_object('items', ARRAY[$txt$Kuah keruh: terlalu sering diaduk atau api terlalu besar — masak api sedang, aduk seperlunya$txt$, $txt$Terlalu asam: tambah air dan sedikit gula merah untuk menyeimbangkan$txt$, $txt$Sayur lembek: urutan salah — bahan keras selalu masuk duluan$txt$, $txt$Asam tengik: asam jawa kebanyakan atau ampas direbus terlalu lama — saring larutan asam$txt$]) FROM madevi.articles v WHERE v.business_code = 'TUT-MASAK19-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 10, jsonb_build_object('text', $txt$Penyelesaian dan Penyajian$txt$) FROM madevi.articles v WHERE v.business_code = 'TUT-MASAK19-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'PARAGRAPH', 11, jsonb_build_object('text', $txt$Sayur asem paling nikmat disajikan hangat dengan nasi putih, ikan asin goreng, sambal terasi, dan lalapan. Sisa sayur asem tahan 2 hari di kulkas — panaskan secukupnya saja, jangan direbus ulang berkali-kali agar sayur tidak hancur.$txt$) FROM madevi.articles v WHERE v.business_code = 'TUT-MASAK19-001';
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 0, jsonb_build_object('text', $txt$Logam yang Menemani Peradaban$txt$) FROM madevi.articles v WHERE v.business_code = 'EXP-KIMIA23-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Perak (simbol Ag, dari bahasa Latin argentum) adalah salah satu dari sedikit logam yang dikenal manusia sejak ribuan tahun lalu, bersama emas dan tembaga. Ia berkilau putih cemerlang, mudah dibentuk, dan sejak zaman kuno dipakai sebagai uang, perhiasan, dan peralatan makan bangsawan. Selama berabad-abad perak bahkan menjadi standar uang dunia sebelum era uang kertas.$txt$) FROM madevi.articles v WHERE v.business_code = 'EXP-KIMIA23-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 2, jsonb_build_object('text', $txt$Sifat-sifat Perak$txt$) FROM madevi.articles v WHERE v.business_code = 'EXP-KIMIA23-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Perak adalah logam dengan daya hantar listrik dan panas tertinggi di antara semua unsur — lebih baik dari tembaga dan emas. Ia sangat lunak: 1 gram perak bisa ditarik menjadi kawat sepanjang 180 meter. Karena terlalu lunak untuk perhiasan, perak biasanya dicampur tembaga menjadi perak sterling (92,5% perak).$txt$) FROM madevi.articles v WHERE v.business_code = 'EXP-KIMIA23-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 4, jsonb_build_object('text', $txt$Mengapa Perak Menghitam?$txt$) FROM madevi.articles v WHERE v.business_code = 'EXP-KIMIA23-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$Perak tidak berkarat seperti besi, tetapi bisa menghitam karena bereaksi dengan senyawa belerang di udara — dari keringat, telur, atau polusi — membentuk lapisan perak sulfida (Ag2S) yang gelap. Inilah mengapa sendok perak menghitam bila dipakai makan telur. Kabar baiknya, noda ini mudah dibersihkan dengan pasta gigi atau larutan soda kue.$txt$) FROM madevi.articles v WHERE v.business_code = 'EXP-KIMIA23-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 6, jsonb_build_object('text', $txt$Kegunaan Modern Perak$txt$) FROM madevi.articles v WHERE v.business_code = 'EXP-KIMIA23-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'LIST', 7, jsonb_build_object('items', ARRAY[$txt$Elektronik: kontak listrik, papan sirkuit, dan panel surya karena daya hantarnya tertinggi$txt$, $txt$Fotografi klasik: film dan kertas foto memakai perak halida yang peka cahaya$txt$, $txt$Medis: sifat antibakteri perak dipakai pada perban luka dan alat bedah$txt$, $txt$Perhiasan dan peralatan makan: perak sterling 925$txt$, $txt$Investasi: koin dan batangan perak sebagai lindung nilai — 'emasnya orang biasa'$txt$]) FROM madevi.articles v WHERE v.business_code = 'EXP-KIMIA23-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 8, jsonb_build_object('text', $txt$Kesimpulan$txt$) FROM madevi.articles v WHERE v.business_code = 'EXP-KIMIA23-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Perak adalah logam istimewa: termulia setelah emas, tetapi juga pekerja keras di dunia industri. Dari koin kuno hingga panel surya modern, kilau perak telah menemani peradaban manusia selama ribuan tahun — dan tampaknya akan terus bersinar di era energi terbarukan.$txt$) FROM madevi.articles v WHERE v.business_code = 'EXP-KIMIA23-001';
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 0, jsonb_build_object('text', $txt$Yogyakarta yang Diduduki$txt$) FROM madevi.articles v WHERE v.business_code = 'EXP-SEJARAH20-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Setelah Agresi Militer Belanda II pada 19 Desember 1948, Yogyakarta — ibu kota Republik Indonesia — jatuh ke tangan Belanda. Presiden Soekarno dan Wakil Presiden Hatta ditawan dan diasingkan. Dunia internasional mulai meragukan: benarkah Republik Indonesia masih ada? Di tengah keraguan itulah TNI merancang serangan balasan untuk membuktikan Indonesia belum kalah.$txt$) FROM madevi.articles v WHERE v.business_code = 'EXP-SEJARAH20-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 2, jsonb_build_object('text', $txt$Perencanaan dan Jalannya Serangan$txt$) FROM madevi.articles v WHERE v.business_code = 'EXP-SEJARAH20-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Serangan dirancang para pemimpin TNI di bawah koordinasi Panglima Besar Jenderal Soedirman yang sedang bergerilya dalam keadaan sakit, dengan Letkol Soeharto memimpin serangan ke Yogyakarta. Tepat pukul 06.00 pada 1 Maret 1949, pasukan TNI menyerbu pos-pos Belanda dari berbagai penjuru kota. Dalam enam jam, kota berhasil dikuasai dan bendera Merah Putih berkibar sebelum pasukan mundur teratur menghindari serangan balasan.$txt$) FROM madevi.articles v WHERE v.business_code = 'EXP-SEJARAH20-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 4, jsonb_build_object('text', $txt$Mengapa Enam Jam Penting?$txt$) FROM madevi.articles v WHERE v.business_code = 'EXP-SEJARAH20-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$Enam jam penguasaan kota bukan soal militer semata — ini soal pesan politik. Berita serangan sampai ke meja perundingan internasional dan telinga para diplomat PBB. Belanda yang mengklaim Republik sudah tidak ada terbukti salah: TNI masih mampu menyerang ibu kota yang dijaga ketat. Serangan ini memperkuat posisi diplomasi Indonesia menuju pengakuan kedaulatan.$txt$) FROM madevi.articles v WHERE v.business_code = 'EXP-SEJARAH20-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 6, jsonb_build_object('text', $txt$Dampak dan Peringatan$txt$) FROM madevi.articles v WHERE v.business_code = 'EXP-SEJARAH20-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Serangan Umum 1 Maret memperkuat argumen Indonesia di forum internasional, menambah tekanan dunia terhadap Belanda, dan membuka jalan ke perundingan Roem-Roijen serta Konferensi Meja Bundar akhir 1949. Peristiwa ini diperingati setiap 1 Maret dan diabadikan dalam Monumen Serangan Umum 1 Maret di kawasan Malioboro, Yogyakarta.$txt$) FROM madevi.articles v WHERE v.business_code = 'EXP-SEJARAH20-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 8, jsonb_build_object('text', $txt$Kesimpulan$txt$) FROM madevi.articles v WHERE v.business_code = 'EXP-SEJARAH20-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Serangan Umum 1 Maret 1949 membuktikan Republik Indonesia tidak padam meski ibu kotanya diduduki. Ia mengajarkan bahwa perjuangan kemerdekaan ditempuh lewat dua jalur sekaligus — senjata dan diplomasi — yang saling menguatkan. Enam jam di Yogyakarta pagi itu mengubah persepsi dunia dan mempercepat jalan menuju kedaulatan penuh.$txt$) FROM madevi.articles v WHERE v.business_code = 'EXP-SEJARAH20-001';
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 0, jsonb_build_object('text', $txt$Tujuan Pembelajaran$txt$) FROM madevi.articles v WHERE v.business_code = 'SCH-SMA-GEO5-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Setelah mempelajari materi ini, kamu diharapkan mampu: (1) menjelaskan konsep wilayah dan perwilayahan; (2) membedakan pewilayahan formal dan fungsional; (3) mengidentifikasi contoh wilayah di Indonesia; (4) menjelaskan manfaat perwilayahan bagi pembangunan.$txt$) FROM madevi.articles v WHERE v.business_code = 'SCH-SMA-GEO5-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 2, jsonb_build_object('text', $txt$Pengertian Wilayah$txt$) FROM madevi.articles v WHERE v.business_code = 'SCH-SMA-GEO5-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Wilayah (region) adalah area di permukaan bumi yang memiliki karakteristik tertentu sehingga dapat dibedakan dari area lain di sekitarnya. Karakteristik itu bisa berupa kenampakan fisik (iklim, tanah, bentang alam) maupun sosial (bahasa, mata pencaharian, budaya). Contoh: wilayah pegunungan Dieng berbeda dari wilayah pesisir Pantura — baik alam maupun cara hidup penduduknya.$txt$) FROM madevi.articles v WHERE v.business_code = 'SCH-SMA-GEO5-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 4, jsonb_build_object('text', $txt$Jenis Wilayah dan Perwilayahan$txt$) FROM madevi.articles v WHERE v.business_code = 'SCH-SMA-GEO5-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$Ada tiga jenis wilayah: (1) Wilayah formal — memiliki ciri seragam, misalnya wilayah iklim tropis; (2) Wilayah fungsional — dipersatukan fungsi yang berpusat pada satu titik, misalnya Jabodetabek yang berpusat di Jakarta; (3) Wilayah vernakular — terbentuk dari persepsi masyarakat, misalnya 'Tanah Pasundan'. Perwilayahan (regionalisasi) adalah proses pengelompokan wilayah berdasarkan kriteria tertentu untuk analisis atau perencanaan, misalnya pembagian Kawasan Barat dan Timur Indonesia.$txt$) FROM madevi.articles v WHERE v.business_code = 'SCH-SMA-GEO5-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 6, jsonb_build_object('text', $txt$Contoh Perwilayahan di Indonesia$txt$) FROM madevi.articles v WHERE v.business_code = 'SCH-SMA-GEO5-001';
