INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'LIST', 9, jsonb_build_object('items', ARRAY[$txt$1. Jelaskan perbedaan wilayah formal dan wilayah fungsional beserta masing-masing satu contoh di Indonesia!$txt$, $txt$2. Mengapa pemerintah perlu melakukan perwilayahan dalam perencanaan pembangunan? Sebutkan 3 alasannya!$txt$, $txt$3. Berikan contoh perwilayahan berdasarkan kriteria fisik dan kriteria sosial di pulaumu!$txt$]) FROM madevi.articles v WHERE v.business_code = 'SCH-SMA-GEO5-001';
