INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'PARAGRAPH', 11, jsonb_build_object('text', $txt$1. Wilayah formal: seragam cirinya (mis. wilayah iklim tropis); wilayah fungsional: dipersatukan fungsi berpusat pada satu nodal (mis. Jabodetabek berpusat di Jakarta). 2. Agar kebijakan sesuai karakteristik wilayah; mengetahui potensi/masalah spesifik; memantau pemerataan pembangunan. 3. Fisik: dataran rendah pantai utara Jawa; sosial: wilayah berbahasa Sunda di Jawa Barat (jawaban dapat bervariasi, asalkan logis).$txt$) FROM madevi.articles v WHERE v.business_code = 'SCH-SMA-GEO5-001';
