INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Setelah belajar materi ini, kamu diharapkan mampu: (1) menjelaskan pengertian kegiatan ekonomi; (2) menyebutkan tiga jenis kegiatan ekonomi beserta contohnya; (3) mengidentifikasi kegiatan ekonomi di lingkungan sekitarmu; (4) menghargai pekerjaan orang lain.$txt$) FROM madevi.articles v WHERE v.business_code = 'SCH-SD-IPS15-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 2, jsonb_build_object('text', $txt$Apa Itu Kegiatan Ekonomi?$txt$) FROM madevi.articles v WHERE v.business_code = 'SCH-SD-IPS15-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Kegiatan ekonomi adalah semua kegiatan manusia untuk memenuhi kebutuhan hidup. Setiap hari kamu melihatnya: ibu membeli sayur di pasar, ayah bekerja di kantor, kakak membuat kue untuk dijual. Secara garis besar, kegiatan ekonomi dibagi menjadi tiga: produksi, distribusi, dan konsumsi.$txt$) FROM madevi.articles v WHERE v.business_code = 'SCH-SD-IPS15-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 4, jsonb_build_object('text', $txt$Produksi, Distribusi, dan Konsumsi$txt$) FROM madevi.articles v WHERE v.business_code = 'SCH-SD-IPS15-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$Produksi adalah kegiatan membuat barang dan jasa — misalnya petani menanam padi dan penjahit membuat baju; pelakunya disebut produsen. Distribusi adalah kegiatan menyalurkan barang dari produsen ke konsumen — misalnya sopir truk mengantar beras dan pedagang pasar menjual sayur; pelakunya disebut distributor. Konsumsi adalah kegiatan memakai barang dan jasa — misalnya kamu makan nasi dan memakai seragam; pelakunya disebut konsumen, dan itu termasuk kamu! Contoh rantai lengkap: petani memanen padi (produksi), pedagang menjual beras ke warung (distribusi), ibu memasak dan keluarga memakannya (konsumsi).$txt$) FROM madevi.articles v WHERE v.business_code = 'SCH-SD-IPS15-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 6, jsonb_build_object('text', $txt$Contoh di Sekitarmu$txt$) FROM madevi.articles v WHERE v.business_code = 'SCH-SD-IPS15-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'LIST', 7, jsonb_build_object('items', ARRAY[$txt$Di desa: bertani, beternak, berkebun, menjadi nelayan$txt$, $txt$Di kota: berdagang, menjadi karyawan, membuka jasa (tukang cukur, bengkel)$txt$, $txt$Di rumah: ibumu yang memasak kue untuk dijual termasuk produsen!$txt$, $txt$Tugas: catat 5 kegiatan ekonomi yang kamu lihat dalam perjalanan ke sekolah$txt$]) FROM madevi.articles v WHERE v.business_code = 'SCH-SD-IPS15-001';
