INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'PARAGRAPH', 11, jsonb_build_object('text', $txt$1. Produksi (membuat barang, mis. petani menanam padi), distribusi (menyalurkan barang, mis. pedagang pasar), konsumsi (memakai barang, mis. makan nasi). 2. Distribusi, karena menyalurkan barang dari produsen (kebun) ke konsumen (pembeli di pasar). 3. Karena setiap pekerjaan penting dan saling membutuhkan; tidak ada pekerjaan yang hina selama halal dan bermanfaat.$txt$) FROM madevi.articles v WHERE v.business_code = 'SCH-SD-IPS15-001';
